package mz.bam.seeky.android;

import android.app.*;import android.content.*;import android.content.pm.ServiceInfo;import android.media.*;import android.media.session.*;import android.net.Uri;import android.os.*;import android.view.Surface;import java.io.File;
/** Single media owner. Activity surfaces can detach without destroying playback. */
public final class MediaPlaybackService extends Service {
 static final String OPEN="seeky.media.OPEN",PLAY="seeky.media.PLAY",PAUSE="seeky.media.PAUSE",STOP="seeky.media.STOP",BACK="seeky.media.BACK",NEXT="seeky.media.NEXT";
 static final int ID=93;final Binder binder=new LocalBinder();final Handler main=new Handler(Looper.getMainLooper());
 MediaPlayer player;MediaSession session;AudioManager audio;AudioFocusRequest focus;Uri uri;String title="Seeky",error="";boolean ready,playing,foreground,repeat,completed;float speed=1;Surface surface;boolean resumeAfterFocus;
 public final class LocalBinder extends Binder {MediaPlaybackService service(){return MediaPlaybackService.this;}}
 public IBinder onBind(Intent i){return binder;}
 final BroadcastReceiver noisy=new BroadcastReceiver(){public void onReceive(Context c,Intent i){pause();}};
 public void onCreate(){super.onCreate();SleepTimer.watch(this,this::pause,this::scheduleSleep);audio=(AudioManager)getSystemService(AUDIO_SERVICE);AudioAttributes a=new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build();focus=new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN).setAudioAttributes(a).setOnAudioFocusChangeListener(change->{if(change==AudioManager.AUDIOFOCUS_GAIN){if(resumeAfterFocus){resumeAfterFocus=false;play();}}else if(change==AudioManager.AUDIOFOCUS_LOSS_TRANSIENT){resumeAfterFocus=playing;if(ready&&player!=null)try{player.pause();}catch(IllegalStateException ignored){}playing=false;main.removeCallbacks(sleepStop);persist(false);publish();}else if(change<0){resumeAfterFocus=false;pause();}}).build();session=new MediaSession(this,"Seeky");session.setFlags(MediaSession.FLAG_HANDLES_MEDIA_BUTTONS|MediaSession.FLAG_HANDLES_TRANSPORT_CONTROLS);session.setCallback(new MediaSession.Callback(){public void onPlay(){play();}public void onPause(){pause();}public void onStop(){stopPlayback();}public void onSeekTo(long p){seek(p);}public void onSkipToPrevious(){skip(-10000);}public void onSkipToNext(){skip(10000);}});session.setActive(true);registerReceiver(noisy,new IntentFilter(AudioManager.ACTION_AUDIO_BECOMING_NOISY));((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(new NotificationChannel("seeky_media","Seeky Media",NotificationManager.IMPORTANCE_LOW));}
 public int onStartCommand(Intent i,int flags,int id){if(i==null){stopSelf();return START_NOT_STICKY;}String action=i.getAction();if(STOP.equals(action)){stopPlayback();return START_NOT_STICKY;}try{ensureForeground();if(OPEN.equals(action)){Uri requested=i.getData();if(requested==null)throw new IllegalArgumentException("Ficheiro indisponível.");if(!requested.equals(uri)||player==null)open(requested,i.getStringExtra("name"));else publish();}else if(PAUSE.equals(action))pause();else if(BACK.equals(action))skip(-10000);else if(NEXT.equals(action))skip(10000);else play();}catch(Exception e){failure(e);}return START_NOT_STICKY;}
 void ensureForeground(){if(foreground)return;Notification n=notification();if(Build.VERSION.SDK_INT>=29)startForeground(ID,n,ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PLAYBACK);else startForeground(ID,n);foreground=true;}
 void open(Uri value,String name)throws Exception {
  if(!"file".equals(value.getScheme())&&!"content".equals(value.getScheme()))throw new IllegalArgumentException("Localização inválida.");
  if("file".equals(value.getScheme())&&!StorageAccess.allowed(this,new File(value.getPath())))throw new SecurityException("Ficheiro sem acesso autorizado.");
  releasePlayer();uri=value;title=name==null?"Seeky":name;error="";speed=1;player=new MediaPlayer();MediaPlayer p=player;
  p.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build());p.setWakeMode(this,PowerManager.PARTIAL_WAKE_LOCK);p.setDataSource(this,uri);if(surface!=null&&surface.isValid())p.setSurface(surface);
  p.setOnPreparedListener(v->{if(player!=v)return;ready=true;completed=false;seek(getSharedPreferences("seeky",0).getInt("reader_audio_"+uri,0));play();main.removeCallbacks(save);main.postDelayed(save,1000);});
  p.setOnCompletionListener(v->{if(player!=v)return;if(uri!=null&&SleepTimer.boundary(this,uri.toString(),0)){playing=false;return;}if(repeat){seek(0);play();}else{playing=false;completed=true;persist(true);audio.abandonAudioFocusRequest(focus);publish();}});
  p.setOnErrorListener((v,what,extra)->{failure(new IllegalStateException("Codec indisponível neste aparelho."));return true;});
  session.setMetadata(new MediaMetadata.Builder().putString(MediaMetadata.METADATA_KEY_TITLE,title).build());p.prepareAsync();publish();
 }
 void play(){resumeAfterFocus=false;if(!ready||player==null)return;try{ensureForeground();if(audio.requestAudioFocus(focus)!=AudioManager.AUDIOFOCUS_REQUEST_GRANTED)return;if(completed){player.seekTo(0);completed=false;}player.start();playing=true;scheduleSleep();publish();}catch(Exception e){failure(e);}}
 void pause(){resumeAfterFocus=false;if(player!=null&&ready)try{if(player.isPlaying())player.pause();}catch(IllegalStateException ignored){}playing=false;main.removeCallbacks(sleepStop);persist(false);if(audio!=null&&focus!=null)audio.abandonAudioFocusRequest(focus);publish();}
 void seek(long p){if(ready&&player!=null)try{player.seekTo((int)Math.max(0,Math.min(Math.max(0,duration()-1),p)));completed=false;scheduleSleep();publish();}catch(IllegalStateException ignored){}}
 void skip(long ms){seek((long)position()+ms);}
 int position(){try{return ready?player.getCurrentPosition():0;}catch(Exception e){return 0;}}
 int duration(){try{return ready?player.getDuration():0;}catch(Exception e){return 0;}}
 void speed(float value){if(!ready)return;try{boolean was=playing;player.setPlaybackParams(player.getPlaybackParams().setSpeed(value));if(!was)player.pause();speed=value;playing=was;scheduleSleep();publish();}catch(Exception e){error="Velocidade indisponível.";}}
 void attach(Surface value){surface=value;if(player!=null)try{player.setSurface(value);}catch(Exception e){AppDiagnostics.record(this,"media-surface",e);}}
 void persist(boolean complete){if(uri!=null&&ready)getSharedPreferences("seeky",0).edit().putInt("reader_audio_"+uri,complete||completed?0:position()).apply();}
 final Runnable save=new Runnable(){public void run(){if(player==null)return;persist(false);if(uri!=null)SleepTimer.media(MediaPlaybackService.this,uri.toString(),position());main.postDelayed(this,1000);}};
 void publish(){if(session==null)return;int state=!error.isEmpty()?PlaybackState.STATE_ERROR:!ready?PlaybackState.STATE_BUFFERING:playing?PlaybackState.STATE_PLAYING:PlaybackState.STATE_PAUSED;session.setPlaybackState(new PlaybackState.Builder().setActions(PlaybackState.ACTION_PLAY|PlaybackState.ACTION_PAUSE|PlaybackState.ACTION_PLAY_PAUSE|PlaybackState.ACTION_STOP|PlaybackState.ACTION_SEEK_TO|PlaybackState.ACTION_SKIP_TO_NEXT|PlaybackState.ACTION_SKIP_TO_PREVIOUS).setState(state,position(),speed).build());if(foreground)((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(ID,notification());}
 PendingIntent action(String value,int id){return PendingIntent.getService(this,id,new Intent(this,MediaPlaybackService.class).setAction(value),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);}
 Notification notification(){Intent open=new Intent(this,MediaActivity.class).setData(uri).putExtra("name",title);PendingIntent screen=PendingIntent.getActivity(this,90,open,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);return new Notification.Builder(this,"seeky_media").setSmallIcon(android.R.drawable.ic_media_play).setContentTitle(title).setContentText(AppLanguage.text(this,error.isEmpty()?playing?"A reproduzir":"Pausado":error)).setContentIntent(screen).setOngoing(playing).setDeleteIntent(action(STOP,95)).setOnlyAlertOnce(true).setVisibility(Notification.VISIBILITY_PUBLIC).addAction(new Notification.Action.Builder(android.R.drawable.ic_media_rew,"−10 s",action(BACK,91)).build()).addAction(new Notification.Action.Builder(playing?android.R.drawable.ic_media_pause:android.R.drawable.ic_media_play,AppLanguage.text(this,playing?"Pausar":"Reproduzir"),action(playing?PAUSE:PLAY,92)).build()).addAction(new Notification.Action.Builder(android.R.drawable.ic_menu_close_clear_cancel,AppLanguage.text(this,"Parar"),action(STOP,94)).build()).setStyle(new Notification.MediaStyle().setMediaSession(session.getSessionToken()).setShowActionsInCompactView(0,1,2)).build();}
 void failure(Exception e){AppDiagnostics.record(this,"media-playback",e);error=e.getMessage()==null?"Não foi possível reproduzir.":e.getMessage();releasePlayer();if(audio!=null)audio.abandonAudioFocusRequest(focus);publish();}
 final Runnable sleepStop=()->{if(uri==null||!ready||!playing)return;long end=SleepTimer.prefs(this).getLong("media_end",0);if(SleepTimer.prefs(this).getInt("mode",0)==2&&SleepTimer.prefs(this).getString("uri","").equals(uri.toString())&&end>0){if(position()>=end-20)SleepTimer.fire(this);else scheduleSleep();}};
 void scheduleSleep(){main.removeCallbacks(sleepStop);if(!ready||!playing||uri==null)return;android.content.SharedPreferences p=SleepTimer.prefs(this);long end=p.getLong("media_end",0);if(p.getInt("mode",0)==2&&p.getString("uri","").equals(uri.toString())&&end>0)main.postDelayed(sleepStop,Math.max(1,(long)((end-position())/Math.max(.5f,speed))));}
 void releasePlayer(){main.removeCallbacks(sleepStop);persist(false);main.removeCallbacks(save);ready=false;playing=false;if(player!=null){try{player.setSurface(null);player.release();}catch(Exception ignored){}player=null;}}
 void stopPlayback(){releasePlayer();audio.abandonAudioFocusRequest(focus);stopForeground(STOP_FOREGROUND_REMOVE);foreground=false;stopSelf();}
 public void onDestroy(){SleepTimer.unwatch(this);releasePlayer();try{unregisterReceiver(noisy);}catch(Exception ignored){}audio.abandonAudioFocusRequest(focus);if(session!=null){session.setActive(false);session.release();}super.onDestroy();}
}
